const FIXTURE: &str = include_str!("../fixtures/node_vectors.tsv");
const RESERVED: [u8; 32] = [7; 32];
const U: u128 = 100_000_000;
const RECIPIENT: &str = "1BitcoinEaterAddressDontSendf59kuE";
const BASE_HEIGHT: u64 = 100;
const BASE_ID: BlockId = BlockId([0x44; 32]);

fn unhex(text: &str) -> Vec<u8> {
    text.as_bytes()
        .chunks_exact(2)
        .map(|pair| u8::from_str_radix(core::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}
#[derive(Clone)]
struct Vector {
    template: BitcoinInputTemplate,
    spending: Vec<u8>,
    amount: u64,
    script: Vec<u8>,
}
fn vector(name: &str) -> Vector {
    let row: Vec<&str> = FIXTURE
        .lines()
        .find(|line| line.starts_with(&format!("{name}\t")))
        .unwrap()
        .split('\t')
        .collect();
    Vector {
        template: if row[1] == "P2wpkh" {
            BitcoinInputTemplate::P2wpkh
        } else {
            BitcoinInputTemplate::P2pkh
        },
        spending: unhex(row[5]),
        amount: row[3].parse().unwrap(),
        script: unhex(row[4]),
    }
}
impl Vector {
    fn address(&self) -> String {
        let hash: [u8; 20] = match self.template {
            BitcoinInputTemplate::P2wpkh => self.script[2..22].try_into().unwrap(),
            _ => self.script[3..23].try_into().unwrap(),
        };
        sender_address(AdmissionNetwork::Regtest, self.template, &hash)
    }
    fn outpoint(&self) -> ParentOutpoint {
        let (txid_raw, vout) = bitcoin_input_outpoint(&self.spending, 0).unwrap();
        ParentOutpoint { txid_raw, vout }
    }
}

fn varint(n: usize) -> Vec<u8> {
    match n {
        0..=252 => vec![n as u8],
        253..=65535 => [vec![253], (n as u16).to_le_bytes().to_vec()].concat(),
        _ => [vec![254], (n as u32).to_le_bytes().to_vec()].concat(),
    }
}
fn outputs(list: &[(u64, Vec<u8>)]) -> Vec<u8> {
    let mut bytes = varint(list.len());
    for (amount, script) in list {
        bytes.extend(amount.to_le_bytes());
        bytes.extend(varint(script.len()));
        bytes.extend(script);
    }
    bytes
}
fn coinbase(tag: u64, commitment: [u8; 32]) -> Vec<u8> {
    let outs = vec![
        (0u64, vec![0x51]),
        (
            0,
            [
                vec![0x6a, 0x24, 0xaa, 0x21, 0xa9, 0xed],
                commitment.to_vec(),
            ]
            .concat(),
        ),
    ];
    let mut bytes = 2u32.to_le_bytes().to_vec();
    bytes.extend([0, 1, 1]);
    bytes.extend([0u8; 32]);
    bytes.extend([0xff; 4]);
    // The tag keeps the coinbases of competing blocks, and their txids, apart.
    bytes.push(9);
    bytes.extend(tag.to_le_bytes());
    bytes.push(0x51);
    bytes.extend([0xff; 4]);
    bytes.extend(outputs(&outs));
    bytes.extend([1, 32]);
    bytes.extend(RESERVED);
    bytes.extend(0u32.to_le_bytes());
    bytes
}
fn display(mut hash: [u8; 32]) -> [u8; 32] {
    hash.reverse();
    hash
}

/// A mined regtest-difficulty block at `height` over `parent`, holding `rest`.
/// `salt` makes the coinbase of competing blocks at one height differ.
fn build_block(height: u64, parent: BlockId, salt: u8, rest: &[Vec<u8>]) -> (Vec<u8>, BlockId) {
    let mut wtxids = vec![[0u8; 32]];
    wtxids.extend(
        rest.iter()
            .map(|raw| inspect_transaction(raw).unwrap().wtxid),
    );
    let witness_root = merkle_root_unverified(&wtxids).unwrap();
    let commitment = merkle_root_unverified(&[witness_root, RESERVED]).unwrap();
    let base = coinbase(height * 256 + u64::from(salt), commitment);
    let mut transactions = vec![base];
    transactions.extend(rest.iter().cloned());
    let txids: Vec<[u8; 32]> = transactions
        .iter()
        .map(|raw| inspect_transaction(raw).unwrap().txid)
        .collect();
    let root = merkle_root_unverified(&txids).unwrap();
    let mut previous = parent.0;
    previous.reverse();
    let mut block = Vec::new();
    for nonce in 0u32.. {
        let mut header = 0x2000_0000u32.to_le_bytes().to_vec();
        header.extend(previous);
        header.extend(root);
        header.extend(1_700_000_000u32.to_le_bytes());
        header.extend(0x207f_ffffu32.to_le_bytes());
        header.extend(nonce.to_le_bytes());
        if CheckedHeader::check_header_at_claimed_height(
            height,
            &header,
            BitcoinPowProfile::RegtestLike,
        )
        .is_ok()
        {
            block = header;
            break;
        }
    }
    block.extend(varint(transactions.len()));
    for raw in &transactions {
        block.extend(raw);
    }
    let view = UnverifiedRawBlockView::parse(&block, None).unwrap();
    let id = BlockId(display(view.header_hash_raw()));
    (block, id)
}

/// A synthetic chain above the base tip: `blocks[i]` is height BASE_HEIGHT+1+i.
#[derive(Clone)]
struct Branch {
    blocks: Vec<(Vec<u8>, BlockId)>,
}
impl Branch {
    /// `fork` is the number of leading blocks shared with `prefix`.
    fn build(prefix: &[(Vec<u8>, BlockId)], salt: u8, txs: &[Vec<Vec<u8>>]) -> Self {
        let mut blocks = prefix.to_vec();
        for rest in txs {
            let height = BASE_HEIGHT + 1 + blocks.len() as u64;
            let parent = blocks.last().map_or(BASE_ID, |b| b.1);
            blocks.push(build_block(height, parent, salt, rest));
        }
        Self { blocks }
    }
    fn tip(&self) -> Tip {
        Tip {
            height: BASE_HEIGHT + self.blocks.len() as u64,
            id: self.blocks.last().unwrap().1,
        }
    }
}

#[derive(Clone, Default)]
struct MockNode(Arc<Mutex<MockState>>);
#[derive(Default)]
struct MockState {
    heights: BTreeMap<u64, BlockId>,
    raws: BTreeMap<BlockId, Vec<u8>>,
}
impl MockNode {
    fn follow(&self, branch: &Branch) {
        let mut state = self.0.lock().unwrap();
        state.heights.clear();
        state.heights.insert(BASE_HEIGHT, BASE_ID);
        for (index, (raw, id)) in branch.blocks.iter().enumerate() {
            state.heights.insert(BASE_HEIGHT + 1 + index as u64, *id);
            state.raws.insert(*id, raw.clone());
        }
    }
}
impl ObservationRpc for MockNode {
    fn verify_identity(&mut self) -> Result<ClaimedNodeIdentity, ObservationRpcError> {
        Ok(ClaimedNodeIdentity {
            network: TradeLayerMainnet::Bitcoin,
            test: false,
            genesis: TradeLayerMainnet::Bitcoin.genesis(),
        })
    }
    fn reported_tip(&mut self) -> Result<Tip, ObservationRpcError> {
        let state = self.0.lock().unwrap();
        let (height, id) = state.heights.iter().next_back().unwrap();
        Ok(Tip {
            height: *height,
            id: *id,
        })
    }
    fn block_hash(&mut self, height: u64) -> Result<BlockId, ObservationRpcError> {
        self.0
            .lock()
            .unwrap()
            .heights
            .get(&height)
            .copied()
            .ok_or(ObservationRpcError::Unavailable)
    }
    fn raw_block(&mut self, hash: BlockId) -> Result<Vec<u8>, ObservationRpcError> {
        self.0
            .lock()
            .unwrap()
            .raws
            .get(&hash)
            .cloned()
            .ok_or(ObservationRpcError::Unavailable)
    }
}

/// Parent outputs by outpoint, and a count of how often a block asked.
#[derive(Clone, Default)]
struct MapProvider {
    outputs: BTreeMap<ParentOutpoint, ParentOutput>,
    asked: Arc<Mutex<Vec<BlockId>>>,
    fail: Arc<Mutex<bool>>,
}
impl MapProvider {
    fn with(vectors: &[&Vector]) -> Self {
        let mut provider = Self::default();
        for v in vectors {
            provider.claim(v, v.amount);
        }
        provider
    }
    fn claim(&mut self, v: &Vector, amount: u64) {
        self.outputs.insert(
            v.outpoint(),
            ParentOutput {
                amount_satoshis: amount,
                script_pubkey: v.script.clone(),
            },
        );
    }
}
struct Parents(BTreeMap<ParentOutpoint, ParentOutput>);
impl ParentOutputSource for Parents {
    fn parent_output(
        &mut self,
        outpoint: &ParentOutpoint,
    ) -> Result<Option<ParentOutput>, ParentSourceError> {
        Ok(self.0.get(outpoint).cloned())
    }
}
impl PrevoutProvider for MapProvider {
    fn parent_source(&mut self, block: BlockId) -> Result<Box<dyn ParentOutputSource>, String> {
        self.asked.lock().unwrap().push(block);
        if *self.fail.lock().unwrap() {
            return Err("prevouts unavailable".into());
        }
        Ok(Box::new(Parents(self.outputs.clone())))
    }
}

struct NoTally;
impl SourceBackend for NoTally {
    fn invoke(&mut self, _: &DependencyCall) -> Result<DependencyReturn, SourceRuleError> {
        Err(SourceRuleError::UnknownDependency)
    }
}

fn account(text: &str) -> AccountId {
    text.try_into().unwrap()
}
fn property() -> PropertyId {
    7.try_into().unwrap()
}
fn txid_of(n: u64) -> TxId {
    let mut bytes = [0; 32];
    bytes[24..].copy_from_slice(&n.to_be_bytes());
    TxId::from_bytes(bytes)
}

struct Actors {
    admin: Vector,
    holder: Vector,
}
fn actors() -> Actors {
    Actors {
        admin: vector("admin-activate"),
        holder: vector("send-p2pkh"),
    }
}

/// The economic chain a node would build: property 7 held by the admin
/// address and the P2PKH holder, listed in the property catalog.
fn economic_chain(actors: &Actors, network: TradeLayerMainnet) -> EconomicChain {
    let admin = actors.admin.address();
    let holder = actors.holder.address();
    let mut ledger = Ledger::new();
    ledger
        .apply(
            txid_of(900),
            Operation::CreateProperty {
                id: property(),
                issuer: account(&admin),
                kind: PropertyKind::Fixed,
                initial_atoms: 100 * U,
            },
        )
        .unwrap();
    ledger
        .apply(
            txid_of(901),
            Operation::Transfer {
                id: property(),
                from: account(&admin),
                to: account(&holder),
                amount_atoms: 40 * U,
            },
        )
        .unwrap();
    let permitted = BTreeSet::from([property()]);
    let joint = JointProtocolState::from_bootstrap_unverified(
        network,
        account(&admin),
        ledger.clone(),
        permitted.clone(),
    )
    .unwrap();
    let mut properties = PropertyCatalog::new();
    let args = vec![
        V::number(7.0),
        V::String("P7".into()),
        V::number(100.0),
        V::String("Fixed".into()),
        V::number(0.0),
        V::String(admin.clone()),
        V::String(admin.clone()),
    ];
    properties
        .execute("addProperty", &args, &mut NoTally)
        .unwrap();
    let owners = SourceCatalogOwners::new(properties, ClearlistSourceOwner::new());
    let economics = EconomicConfig {
        native_entitlements: None,
        insurance: None,
        network,
        contract: 1.try_into().unwrap(),
        collateral: property(),
        inverse: false,
        notional: "1".parse().unwrap(),
        initial_margin_per_contract: "1".parse().unwrap(),
        fee_route: FeeRoute::Native(1),
        policy: SettlementPolicy::ConservingV1,
        funding: None,
        marking: None,
        liquidation: None,
        amm: None,
        contract_binding: None,
        source_consensus: Some(SourceConsensusConfig {
            bootstrap_commitment: EconomicState::source_bootstrap_commitment(&joint).unwrap(),
            catalog_bootstrap_commitment: Some(catalog_commitment(
                &owners.checkpoint_bytes().unwrap(),
            )),
            policy: SourceConsensusPolicy::ConservingSequentialV1,
        }),
    };
    EconomicChain::new_with_source_catalogs_unverified(
        EconomicChainConfig {
            economics,
            admin: account(&admin),
            permitted_spot_properties: permitted,
            rollback_limit: 8,
        },
        ledger,
        owners,
    )
    .unwrap()
}

fn ingest(mode: SourceBlockMode) -> NodeIngest {
    NodeIngest::new(NodeIngestConfig {
        binding: NodeBinding {
            network: TradeLayerMainnet::Bitcoin,
            base: Tip {
                height: BASE_HEIGHT,
                id: BASE_ID,
            },
        },
        admission_network: AdmissionNetwork::Regtest,
        pow: BitcoinPowProfile::RegtestLike,
        rules: BitcoinWitnessRules::SegwitActive,
        mode,
    })
}

static COUNTER: AtomicU64 = AtomicU64::new(0);
struct Dirs {
    root: PathBuf,
}
impl Dirs {
    fn new() -> Self {
        let root = std::env::temp_dir().join(format!(
            "tl-node-ingest-{}-{}",
            std::process::id(),
            COUNTER.fetch_add(1, Ordering::SeqCst)
        ));
        std::fs::create_dir_all(root.join("economic")).unwrap();
        std::fs::create_dir_all(root.join("observer")).unwrap();
        Self { root }
    }
    fn economic(&self) -> PathBuf {
        self.root.join("economic")
    }
    fn observer(&self) -> PathBuf {
        self.root.join("observer")
    }
}
impl Drop for Dirs {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.root);
    }
}

fn observer_config() -> ObserverConfig {
    ObserverConfig::new(
        TradeLayerMainnet::Bitcoin,
        Tip {
            height: BASE_HEIGHT,
            id: BASE_ID,
        },
    )
    .unwrap()
}

type Runner = NodeRunner<MockNode, MapProvider>;

fn new_runner(
    dirs: &Dirs,
    node: &MockNode,
    provider: MapProvider,
    mode: SourceBlockMode,
) -> Runner {
    let actors = actors();
    let chain = economic_chain(&actors, TradeLayerMainnet::Bitcoin);
    let tip = chain.tip();
    let durable = DurableEconomicChain::initialize(&dirs.economic(), chain, tip).unwrap();
    let store = ObservationStore::initialize(&dirs.observer(), observer_config()).unwrap();
    let service = NodeHttpService::new(
        durable,
        None,
        Duration::from_secs(1),
        NodeStatus::new(Tip {
            height: BASE_HEIGHT,
            id: BASE_ID,
        }),
    )
    .unwrap();
    NodeRunner::new(
        Daemon::new(node.clone(), store),
        service,
        provider,
        ingest(mode),
    )
}

/// Steps until the economic chain stands at `observed_height`, or panics.
fn run_to(runner: &mut Runner, observed_height: u64, now: &mut u64) -> Vec<NodeEvent> {
    let control = BootstrapControl::default();
    let mut events = Vec::new();
    for _ in 0..400 {
        let tip = runner.service().economic_chain().unwrap().tip();
        if tip.height + BASE_HEIGHT == observed_height {
            return events;
        }
        *now += 11_000;
        events.extend(runner.step(*now, &control).unwrap());
    }
    panic!("did not reach observed height {observed_height}");
}

fn tx_block(names: &[&str]) -> Vec<Vec<u8>> {
    names.iter().map(|n| vector(n).spending).collect()
}
fn provider_for(names: &[&str]) -> MapProvider {
    let vectors: Vec<Vector> = names.iter().map(|n| vector(n)).collect();
    MapProvider::with(&vectors.iter().collect::<Vec<_>>())
}
fn balance(runner: &Runner, who: &str) -> u128 {
    runner
        .service()
        .economic_chain()
        .unwrap()
        .state()
        .ledger()
        .available_atoms(property(), &account(who))
}
fn state_bytes(runner: &Runner) -> Vec<u8> {
    runner
        .service()
        .economic_chain()
        .unwrap()
        .state()
        .snapshot_bytes()
        .unwrap()
}

#[test]
fn authenticated_send_changes_the_ledger_as_the_source_runner_defines() {
    let actors = actors();
    let node = MockNode::default();
    let branch = Branch::build(
        &[],
        0,
        &[
            tx_block(&["admin-activate"]),
            tx_block(&["send-p2wpkh-a", "send-p2pkh"]),
        ],
    );
    node.follow(&branch);
    let dirs = Dirs::new();
    let mut runner = new_runner(
        &dirs,
        &node,
        provider_for(&["admin-activate", "send-p2wpkh-a", "send-p2pkh"]),
        SourceBlockMode::IndexedReplay,
    );
    let mut now = 0;
    let events = run_to(&mut runner, BASE_HEIGHT + 2, &mut now);
    let admin = actors.admin.address();
    let holder = actors.holder.address();
    // Admin: 60 held after the 40 transfer, minus the 10-unit send; the holder
    // (P2PKH) sends 3 units. The recipient receives both.
    assert_eq!(balance(&runner, &admin), 60 * U - 10 * U);
    assert_eq!(balance(&runner, &holder), 40 * U - 3 * U);
    assert_eq!(balance(&runner, RECIPIENT), 13 * U);
    let reports: Vec<_> = events
        .iter()
        .filter_map(|event| match event {
            NodeEvent::Applied(report) => Some(report),
            _ => None,
        })
        .collect();
    assert_eq!(reports.len(), 2);
    assert_eq!(reports[0].economic_height, 1);
    assert_eq!(
        (
            reports[0].authenticated,
            reports[0].submitted,
            reports[0].source.accepted
        ),
        (1, 1, 1)
    );
    assert_eq!(
        (
            reports[1].authenticated,
            reports[1].submitted,
            reports[1].source.accepted
        ),
        (2, 2, 2)
    );
    let status = runner.service().status();
    assert!(status.authenticated_admission);
    assert_eq!(status.admitted_blocks, 2);
    assert_eq!(status.applied_candidates, 3);
}

#[test]
fn a_refused_candidate_changes_nothing() {
    let actors = actors();
    let node = MockNode::default();
    let branch = Branch::build(
        &[],
        0,
        &[tx_block(&["admin-activate"]), tx_block(&["send-p2wpkh-a"])],
    );
    node.follow(&branch);
    // The parent source claims 9,999 satoshis; the P2WPKH signature commits
    // to 10,000, so verification fails and the send is refused.
    let mut provider = provider_for(&["admin-activate"]);
    provider.claim(&vector("send-p2wpkh-a"), 9_999);
    let dirs = Dirs::new();
    let mut runner = new_runner(&dirs, &node, provider, SourceBlockMode::IndexedReplay);
    let mut now = 0;
    let events = run_to(&mut runner, BASE_HEIGHT + 2, &mut now);
    let refused = events
        .iter()
        .find_map(|event| match event {
            NodeEvent::Applied(report) if report.economic_height == 2 => Some(report.clone()),
            _ => None,
        })
        .unwrap();
    assert_eq!((refused.candidates, refused.authenticated), (1, 0));
    assert_eq!((refused.refused_total, refused.submitted), (1, 0));
    assert!(refused.refused[0].reason.contains("Verification"));
    let admin = actors.admin.address();
    assert_eq!(balance(&runner, &admin), 60 * U);
    assert_eq!(balance(&runner, RECIPIENT), 0);
    // The source frame records no candidate: nothing unauthenticated reaches
    // the runner.
    let chain = runner.service().economic_chain().unwrap();
    let frames = &chain.state().source_consensus_state().frames;
    assert_eq!(frames.len(), 2);
    assert!(frames[1].transactions.is_empty());
}

#[test]
fn an_authenticated_candidate_the_source_rejects_is_recorded_and_changes_nothing() {
    let actors = actors();
    let node = MockNode::default();
    // The send precedes the activation block: the source rejects it.
    let branch = Branch::build(
        &[],
        0,
        &[tx_block(&["send-p2wpkh-a"]), tx_block(&["admin-activate"])],
    );
    node.follow(&branch);
    let dirs = Dirs::new();
    let mut runner = new_runner(
        &dirs,
        &node,
        provider_for(&["admin-activate", "send-p2wpkh-a"]),
        SourceBlockMode::IndexedReplay,
    );
    let mut now = 0;
    let events = run_to(&mut runner, BASE_HEIGHT + 1, &mut now);
    let report = events
        .iter()
        .find_map(|event| match event {
            NodeEvent::Applied(report) => Some(report.clone()),
            _ => None,
        })
        .unwrap();
    assert_eq!((report.authenticated, report.submitted), (1, 1));
    assert_eq!((report.source.accepted, report.source.rejected), (0, 1));
    assert_eq!(balance(&runner, &actors.admin.address()), 60 * U);
    assert_eq!(balance(&runner, RECIPIENT), 0);
}

#[test]
fn the_source_row_carries_the_documented_fields() {
    let node = MockNode::default();
    let branch = Branch::build(&[], 0, &[tx_block(&["send-p2wpkh-a"])]);
    node.follow(&branch);
    let dirs = Dirs::new();
    let provider = provider_for(&["send-p2wpkh-a"]);
    let mut runner = new_runner(&dirs, &node, provider.clone(), SourceBlockMode::Realtime);
    let mut now = 0;
    run_to(&mut runner, BASE_HEIGHT + 1, &mut now);
    let chain = runner.service().economic_chain().unwrap();
    let frame = &chain.state().source_consensus_state().frames[0];
    assert_eq!(frame.mode, SourceBlockMode::Realtime);
    assert_eq!(frame.header.height, 1);
    assert_eq!(frame.header.parent, TradeLayerMainnet::Bitcoin.genesis());
    let row = &frame.transactions[0];
    let v = vector("send-p2wpkh-a");
    let (txid_raw, _) = bitcoin_input_outpoint(&v.spending, 0).unwrap();
    assert_eq!(row.position, 1);
    assert_eq!(row.payload, format!("20;{RECIPIENT};7;a"));
    assert_eq!(row.marker, V::String("tl".into()));
    assert_eq!(row.sender, V::String(v.address()));
    assert_eq!(row.sender_amount, V::number(10_000.0 / 1e8));
    let tx = inspect_transaction(&v.spending).unwrap();
    assert_eq!(row.txid.as_bytes(), display(tx.txid));
    assert_ne!(txid_raw, tx.txid);
    // The only non-carrier output is the P2WPKH change output at vout 1.
    let V::Array(reference) = &row.reference else {
        panic!("reference is not an array");
    };
    assert_eq!(reference.len(), 1);
    assert_eq!(reference[0].get("vout"), V::number(1.0));
    assert_eq!(reference[0].get("satoshis"), V::number(9_000.0));
    assert!(matches!(reference[0].get("address"), V::String(a) if a.starts_with("bcrt1q")));
    assert_eq!(row.reference_amount, V::number(9_000.0 / 1e8));
    // Only the block with a candidate asks for parent outputs.
    assert_eq!(*provider.asked.lock().unwrap(), vec![branch.blocks[0].1]);
}

#[test]
fn a_reorg_replaces_the_applied_block_and_equals_the_winning_branch_from_scratch() {
    let node = MockNode::default();
    let all = [
        "admin-activate",
        "send-p2wpkh-a",
        "send-p2wpkh-b",
        "send-p2pkh",
    ];
    let shared = Branch::build(&[], 0, &[tx_block(&["admin-activate"])]);
    let losing = Branch::build(&shared.blocks, 1, &[tx_block(&["send-p2wpkh-a"])]);
    let winning = Branch::build(
        &shared.blocks,
        2,
        &[tx_block(&["send-p2wpkh-b", "send-p2pkh"]), Vec::new()],
    );
    assert_ne!(losing.blocks[1].1, winning.blocks[1].1);

    let dirs = Dirs::new();
    node.follow(&losing);
    let provider = provider_for(&all);
    let mut runner = new_runner(
        &dirs,
        &node,
        provider.clone(),
        SourceBlockMode::IndexedReplay,
    );
    let mut now = 0;
    run_to(&mut runner, BASE_HEIGHT + 2, &mut now);
    let admin = actors().admin.address();
    assert_eq!(balance(&runner, &admin), 50 * U);
    assert_eq!(balance(&runner, RECIPIENT), 10 * U);

    // The node switches to the longer branch.
    node.follow(&winning);
    let control = BootstrapControl::default();
    let mut reorganized = None;
    for _ in 0..200 {
        now += 11_000;
        for event in runner.step(now, &control).unwrap() {
            if let NodeEvent::Reorganized { from, to } = event {
                reorganized = Some((from, to));
            }
        }
        if runner.service().economic_chain().unwrap().tip().height == 3 {
            break;
        }
    }
    let (from, to) = reorganized.expect("the observer reported a fork");
    assert_eq!(from, losing.tip());
    assert_eq!(
        to,
        Tip {
            height: BASE_HEIGHT + 1,
            id: shared.blocks[0].1
        }
    );
    assert_eq!(
        runner.service().economic_chain().unwrap().tip().id,
        winning.tip().id
    );
    assert_eq!(runner.service().status().rolled_back_blocks, 1);
    // The losing send is gone; the winning branch's sends are in.
    assert_eq!(balance(&runner, &admin), 60 * U - 5 * U);
    assert_eq!(balance(&runner, RECIPIENT), 8 * U);

    // Applying the winning branch from scratch yields the same economic state.
    let scratch_dirs = Dirs::new();
    let scratch_node = MockNode::default();
    scratch_node.follow(&winning);
    let mut scratch = new_runner(
        &scratch_dirs,
        &scratch_node,
        provider.clone(),
        SourceBlockMode::IndexedReplay,
    );
    let mut scratch_now = 0;
    run_to(&mut scratch, BASE_HEIGHT + 3, &mut scratch_now);
    assert_eq!(state_bytes(&runner), state_bytes(&scratch));
    // Rollback restored the shared prefix exactly: even the retained rollback
    // history is the same as the scratch run's.
    assert_eq!(
        runner
            .service()
            .economic_chain()
            .unwrap()
            .checkpoint_bytes()
            .unwrap(),
        scratch
            .service()
            .economic_chain()
            .unwrap()
            .checkpoint_bytes()
            .unwrap()
    );
}

#[test]
fn restart_from_the_durable_stores_resumes() {
    let node = MockNode::default();
    let branch = Branch::build(
        &[],
        0,
        &[
            tx_block(&["admin-activate"]),
            tx_block(&["send-p2wpkh-a"]),
            tx_block(&["send-p2wpkh-b"]),
        ],
    );
    node.follow(&branch);
    let names = ["admin-activate", "send-p2wpkh-a", "send-p2wpkh-b"];
    let dirs = Dirs::new();
    let mut runner = new_runner(
        &dirs,
        &node,
        provider_for(&names),
        SourceBlockMode::IndexedReplay,
    );
    let mut now = 0;
    run_to(&mut runner, BASE_HEIGHT + 2, &mut now);
    let (daemon, service) = runner.into_parts();
    let observer_head = daemon.head().unwrap();
    let owner = service.into_owner();
    let economic_head: EconomicHead = owner.head().unwrap();
    let config = owner.chain().unwrap().config().clone();
    drop(daemon);
    drop(owner);

    let (owner, _) = DurableEconomicChain::load(
        &dirs.economic(),
        config,
        economic_head,
        Recovery::RejectIncompleteTail,
    )
    .unwrap();
    let (store, _) = ObservationStore::load(
        &dirs.observer(),
        observer_config(),
        observer_head,
        Recovery::RejectIncompleteTail,
    )
    .unwrap();
    let service = NodeHttpService::new(
        owner,
        None,
        Duration::from_secs(1),
        NodeStatus::new(Tip {
            height: BASE_HEIGHT,
            id: BASE_ID,
        }),
    )
    .unwrap();
    let mut resumed = NodeRunner::new(
        Daemon::new(node.clone(), store),
        service,
        provider_for(&names),
        ingest(SourceBlockMode::IndexedReplay),
    );
    // Nothing from the first process is claimed as admitted by this one.
    assert!(!resumed.service().status().authenticated_admission);
    assert_eq!(resumed.service().economic_chain().unwrap().tip().height, 2);
    run_to(&mut resumed, BASE_HEIGHT + 3, &mut now);
    assert_eq!(resumed.service().economic_chain().unwrap().tip().height, 3);
    assert_eq!(resumed.service().status().admitted_blocks, 1);
    assert!(resumed.service().status().authenticated_admission);

    // The same three blocks in one process give the same state.
    let scratch_dirs = Dirs::new();
    let mut scratch = new_runner(
        &scratch_dirs,
        &node,
        provider_for(&names),
        SourceBlockMode::IndexedReplay,
    );
    let mut scratch_now = 0;
    run_to(&mut scratch, BASE_HEIGHT + 3, &mut scratch_now);
    assert_eq!(state_bytes(&resumed), state_bytes(&scratch));
}

/// An economic chain that applied `branch` up to observed `height`, with its
/// stores closed: the owner, ready for another runner, and the directory
/// guard that keeps its copy alive.
fn economic_owner_at(branch: &Branch, height: u64) -> (DurableEconomicChain, Dirs) {
    let node = MockNode::default();
    node.follow(branch);
    let dirs = Dirs::new();
    let mut runner = new_runner(
        &dirs,
        &node,
        provider_for(&["admin-activate"]),
        SourceBlockMode::IndexedReplay,
    );
    let mut now = 0;
    run_to(&mut runner, height, &mut now);
    let (daemon, service) = runner.into_parts();
    drop(daemon);
    let owner = service.into_owner();
    let head = owner.head().unwrap();
    let config = owner.chain().unwrap().config().clone();
    drop(owner);
    let keep = Dirs::new();
    copy_dir(&dirs.economic(), &keep.economic());
    let (owner, _) = DurableEconomicChain::load(
        &keep.economic(),
        config,
        head,
        Recovery::RejectIncompleteTail,
    )
    .unwrap();
    (owner, keep)
}
fn copy_dir(from: &std::path::Path, to: &std::path::Path) {
    for entry in std::fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let target = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            std::fs::create_dir_all(&target).unwrap();
            copy_dir(&entry.path(), &target);
        } else {
            std::fs::copy(entry.path(), target).unwrap();
        }
    }
}
fn runner_over(owner: DurableEconomicChain, node: &MockNode, anchor: Tip, dirs: &Dirs) -> Runner {
    let store = ObservationStore::initialize(
        &dirs.observer(),
        ObserverConfig::new(TradeLayerMainnet::Bitcoin, anchor).unwrap(),
    )
    .unwrap();
    let service = NodeHttpService::new(
        owner,
        None,
        Duration::from_secs(1),
        NodeStatus::new(Tip {
            height: BASE_HEIGHT,
            id: BASE_ID,
        }),
    )
    .unwrap();
    NodeRunner::new(
        Daemon::new(node.clone(), store),
        service,
        provider_for(&["admin-activate"]),
        ingest(SourceBlockMode::IndexedReplay),
    )
}
fn first_error(runner: &mut Runner) -> NodeError {
    let control = BootstrapControl::default();
    let mut now = 0;
    for _ in 0..50 {
        now += 11_000;
        if let Err(error) = runner.step(now, &control) {
            return error;
        }
    }
    panic!("no error");
}

#[test]
fn an_economic_tip_off_the_observers_chain_rolls_back_to_the_shared_block() {
    let first = Branch::build(&[], 1, &[tx_block(&["admin-activate"])]);
    let other = Branch::build(&[], 2, &[tx_block(&["admin-activate"]), Vec::new()]);
    assert_ne!(first.blocks[0].1, other.blocks[0].1);
    let (owner, _keep) = economic_owner_at(&first, BASE_HEIGHT + 1);
    // A fresh observer on the other branch has not seen a fork (it never
    // stored the old block); the economic chain shares the base with it and
    // goes back there before following the other branch.
    let node = MockNode::default();
    node.follow(&other);
    let dirs = Dirs::new();
    let mut runner = runner_over(
        owner,
        &node,
        Tip {
            height: BASE_HEIGHT,
            id: BASE_ID,
        },
        &dirs,
    );
    let mut now = 0;
    let events = run_to(&mut runner, BASE_HEIGHT + 2, &mut now);
    assert!(events
        .iter()
        .any(|e| matches!(e, NodeEvent::Reorganized { to, .. } if to.height == BASE_HEIGHT)));
    assert_eq!(
        runner.service().economic_chain().unwrap().tip().id,
        other.tip().id
    );
    assert_eq!(runner.service().status().rolled_back_blocks, 1);
}

#[test]
fn a_height_or_chain_mismatch_is_refused() {
    let branch = Branch::build(&[], 1, &[tx_block(&["admin-activate"])]);
    let longer = Branch::build(&branch.blocks, 1, &[Vec::new(), Vec::new(), Vec::new()]);

    // Gap: the observer starts above the economic tip, at observed height 103
    // while the economic chain stands at 101.
    let (owner, _keep) = economic_owner_at(&branch, BASE_HEIGHT + 1);
    let node = MockNode::default();
    node.follow(&longer);
    let dirs = Dirs::new();
    let anchor = Tip {
        height: BASE_HEIGHT + 3,
        id: longer.blocks[2].1,
    };
    let mut runner = runner_over(owner, &node, anchor, &dirs);
    let error = first_error(&mut runner);
    assert!(
        matches!(&error, NodeError::Ingest(IngestError::Misaligned(why)) if why.contains("below")),
        "{error:?}"
    );
    assert_eq!(runner.service().economic_chain().unwrap().tip().height, 1);
    assert_eq!(runner.service().status().admitted_blocks, 0);

    // A different base: the observer's anchor at the base height is another
    // block, so the two chains share nothing.
    let (owner, _keep) = economic_owner_at(&branch, BASE_HEIGHT + 1);
    let other_base = BlockId([0x55; 32]);
    let (raw, id) = build_block(BASE_HEIGHT + 1, other_base, 9, &[]);
    let node = MockNode::default();
    {
        let mut state = node.0.lock().unwrap();
        state.heights.insert(BASE_HEIGHT, other_base);
        state.heights.insert(BASE_HEIGHT + 1, id);
        state.raws.insert(id, raw);
    }
    let dirs = Dirs::new();
    let mut runner = runner_over(
        owner,
        &node,
        Tip {
            height: BASE_HEIGHT,
            id: other_base,
        },
        &dirs,
    );
    let error = first_error(&mut runner);
    assert!(
        matches!(&error, NodeError::Ingest(IngestError::Misaligned(why)) if why.contains("share no block")),
        "{error:?}"
    );
    assert_eq!(runner.service().economic_chain().unwrap().tip().height, 1);
    assert_eq!(runner.service().status().admitted_blocks, 0);
}

#[test]
fn binding_maps_heights_and_refuses_blocks_that_do_not_extend_the_base() {
    let binding = NodeBinding {
        network: TradeLayerMainnet::Bitcoin,
        base: Tip {
            height: 100,
            id: BASE_ID,
        },
    };
    let header = |height, id: u8, parent: BlockId| BlockHeader {
        height,
        id: BlockId([id; 32]),
        parent,
    };
    let first = binding.economic_header(header(101, 1, BASE_ID)).unwrap();
    assert_eq!(first.height, 1);
    assert_eq!(first.parent, TradeLayerMainnet::Bitcoin.genesis());
    let second = binding
        .economic_header(header(102, 2, BlockId([1; 32])))
        .unwrap();
    assert_eq!((second.height, second.parent), (2, BlockId([1; 32])));
    assert!(binding.economic_header(header(100, 1, BASE_ID)).is_err());
    assert!(binding.economic_header(header(50, 1, BASE_ID)).is_err());
    assert!(binding
        .economic_header(header(101, 1, BlockId([9; 32])))
        .is_err());
    let genesis_tip = Tip {
        height: 0,
        id: TradeLayerMainnet::Bitcoin.genesis(),
    };
    assert_eq!(binding.observed_tip(genesis_tip), binding.base);
    assert_eq!(binding.economic_tip(binding.base), Some(genesis_tip));
    assert_eq!(
        binding.economic_tip(Tip {
            height: 100,
            id: BlockId([8; 32])
        }),
        None
    );
    assert_eq!(
        binding.economic_tip(Tip {
            height: 99,
            id: BASE_ID
        }),
        None
    );
    // The identity map when the base is the genesis.
    let identity = NodeBinding {
        network: TradeLayerMainnet::Bitcoin,
        base: genesis_tip,
    };
    let h = identity
        .economic_header(header(1, 1, genesis_tip.id))
        .unwrap();
    assert_eq!((h.height, h.parent), (1, genesis_tip.id));
}

#[test]
fn a_prevout_outage_stops_the_block_instead_of_refusing_its_candidates() {
    let node = MockNode::default();
    let branch = Branch::build(&[], 0, &[tx_block(&["admin-activate"])]);
    node.follow(&branch);
    let provider = provider_for(&["admin-activate"]);
    *provider.fail.lock().unwrap() = true;
    let dirs = Dirs::new();
    let mut runner = new_runner(
        &dirs,
        &node,
        provider.clone(),
        SourceBlockMode::IndexedReplay,
    );
    let control = BootstrapControl::default();
    let mut now = 0;
    let mut failure = None;
    for _ in 0..50 {
        now += 11_000;
        if let Err(error) = runner.step(now, &control) {
            failure = Some(error);
            break;
        }
    }
    assert!(
        matches!(
            failure,
            Some(NodeError::Ingest(IngestError::PrevoutsUnavailable(_)))
        ),
        "{failure:?}"
    );
    assert_eq!(runner.service().economic_chain().unwrap().tip().height, 0);
    // After the outage the same block applies.
    *provider.fail.lock().unwrap() = false;
    run_to(&mut runner, BASE_HEIGHT + 1, &mut now);
    assert_eq!(runner.service().economic_chain().unwrap().tip().height, 1);
}

#[test]
fn status_over_loopback_reports_admission_only_after_an_admitted_block() {
    let node = MockNode::default();
    let branch = Branch::build(&[], 0, &[tx_block(&["admin-activate"]), Vec::new()]);
    node.follow(&branch);
    let dirs = Dirs::new();
    let actors = actors();
    let chain = economic_chain(&actors, TradeLayerMainnet::Bitcoin);
    let tip = chain.tip();
    let durable = DurableEconomicChain::initialize(&dirs.economic(), chain, tip).unwrap();
    let store = ObservationStore::initialize(&dirs.observer(), observer_config()).unwrap();
    let service = NodeHttpService::new(
        durable,
        Some("127.0.0.1:0".parse().unwrap()),
        Duration::from_secs(2),
        NodeStatus::new(Tip {
            height: BASE_HEIGHT,
            id: BASE_ID,
        }),
    )
    .unwrap();
    let addr = service.local_addr().unwrap().unwrap();
    let mut runner = NodeRunner::new(
        Daemon::new(node.clone(), store),
        service,
        provider_for(&["admin-activate"]),
        ingest(SourceBlockMode::IndexedReplay),
    );
    let control = BootstrapControl::default();
    let query = |runner: &Runner| -> String {
        let handle = std::thread::spawn(move || {
            let mut stream = TcpStream::connect(addr).unwrap();
            stream
                .set_read_timeout(Some(Duration::from_secs(5)))
                .unwrap();
            stream
                .write_all(
                    format!("GET /initstatus HTTP/1.1\r\nHost: {addr}\r\nContent-Type: application/json\r\nContent-Length: 0\r\nConnection: close\r\n\r\n")
                        .as_bytes(),
                )
                .unwrap();
            let mut text = String::new();
            stream.read_to_string(&mut text).unwrap();
            text
        });
        for _ in 0..500 {
            runner.serve(&control).unwrap();
            if handle.is_finished() {
                break;
            }
            std::thread::sleep(Duration::from_millis(2));
        }
        handle.join().unwrap()
    };
    let before = query(&runner);
    assert!(
        before.contains("\"authenticated_admission\":false"),
        "{before}"
    );
    assert!(before.contains("\"admitted_blocks\":0"), "{before}");
    assert!(before.contains("\"admission_scope\":\"input0-p2pkh-p2wpkh-sighash-all\""));
    let mut now = 0;
    run_to(&mut runner, BASE_HEIGHT + 2, &mut now);
    let after = query(&runner);
    assert!(
        after.contains("\"authenticated_admission\":true"),
        "{after}"
    );
    assert!(after.contains("\"admitted_blocks\":2"), "{after}");
    assert!(after.contains("\"applied_candidates\":1"), "{after}");
    assert!(
        after.contains(&format!("\"height_base\":\"{BASE_HEIGHT}:")),
        "{after}"
    );
}

#[test]
fn source_config_is_strict_and_pins_the_collateral_seed_bootstrap() {
    let actors = actors();
    let mut chain_config = economic_chain(&actors, TradeLayerMainnet::Bitcoin)
        .config()
        .clone();
    chain_config.economics.source_consensus = None;
    chain_config.permitted_spot_properties.clear();
    let seed = 5 * U;
    let (ledger, catalogs) = commitments_for_bootstrap(&chain_config, seed).unwrap();
    let config = NodeSourceConfig {
        policy: SourceConsensusPolicy::ConservingSequentialV2,
        block_mode: SourceBlockMode::Realtime,
        collateral_seed_atoms: seed,
        bootstrap_commitment: ledger,
        catalog_bootstrap_commitment: catalogs,
    };
    let text = render_source_config(&config);
    assert_eq!(parse_source_config(&text).unwrap(), config);
    for (broken, why) in [
        (
            text.replace("format = tradelayer-node-source-v1", "format = x"),
            "format",
        ),
        (text.replace("policy", "polic"), "unknown"),
        (
            format!("{text}policy = conserving-sequential-v1\n"),
            "duplicate",
        ),
        (text.replace("block_mode = realtime\n", ""), "missing"),
        (
            text.replace("bootstrap = collateral-seed", "bootstrap = funded"),
            "bootstrap",
        ),
        (text.replace("realtime", "live"), "mode"),
        (text.to_uppercase(), "case"),
        (text.replace("500000000", "0500000000"), "leading zero"),
        (text.replace("500000000", "0"), "zero seed"),
    ] {
        assert!(parse_source_config(&broken).is_err(), "{why}");
    }
    apply_source_config(&mut chain_config, &config).unwrap();
    assert!(matches!(
        apply_source_config(&mut chain_config, &config),
        Err(NodeConfigError::SourceAlreadyConfigured)
    ));
    let chain = fresh_chain(chain_config.clone(), seed).unwrap();
    assert_eq!(
        chain
            .state()
            .ledger()
            .available_atoms(chain_config.economics.collateral, &chain_config.admin),
        seed
    );
    // A different seed is a different bootstrap.
    assert!(matches!(
        fresh_chain(chain_config.clone(), seed + 1),
        Err(NodeConfigError::CommitmentMismatch)
    ));
    let mut wrong = chain_config;
    wrong
        .economics
        .source_consensus
        .as_mut()
        .unwrap()
        .bootstrap_commitment[0] ^= 1;
    assert!(matches!(
        fresh_chain(wrong, seed),
        Err(NodeConfigError::CommitmentMismatch)
    ));
}

#[test]
fn observer_rotation_keeps_the_chains_aligned_and_a_fork_after_it_still_resolves() {
    let node = MockNode::default();
    let empty = |count: usize| -> Vec<Vec<Vec<u8>>> { (0..count).map(|_| Vec::new()).collect() };
    // 8 shared empty blocks; the fork replaces the last two and adds one.
    let shared = Branch::build(&[], 0, &empty(8));
    let losing = Branch::build(&shared.blocks[..6], 1, &empty(2));
    let winning = Branch::build(&shared.blocks[..6], 2, &empty(3));
    let dirs = Dirs::new();
    node.follow(&shared);
    let runner = new_runner(
        &dirs,
        &node,
        MapProvider::default(),
        SourceBlockMode::IndexedReplay,
    );
    let observer_root = dirs.root.clone();
    let mut generation = 0u64;
    let mut runner = runner
        .with_rotation_at(5, 2)
        .with_rotation(Box::new(move |anchor| {
            generation += 1;
            let root = observer_root.join(format!("observer-{generation}"));
            std::fs::create_dir_all(&root).unwrap();
            let config = ObserverConfig::new(TradeLayerMainnet::Bitcoin, anchor)?;
            ObservationStore::initialize(&root, config)
        }));
    let mut now = 0;
    let events = run_to(&mut runner, BASE_HEIGHT + 8, &mut now);
    let rotations: Vec<Tip> = events
        .iter()
        .filter_map(|event| match event {
            NodeEvent::Rotated { anchor } => Some(*anchor),
            _ => None,
        })
        .collect();
    assert!(!rotations.is_empty());
    assert!(rotations[0].height > BASE_HEIGHT);
    let stored = runner.observer().status().unwrap().stored_blocks;
    assert!(stored < 5, "{stored}");
    assert_eq!(runner.service().status().admitted_blocks, 8);

    // A fork two blocks deep, after the rotation.
    node.follow(&losing);
    let control = BootstrapControl::default();
    run_to_reorg(&mut runner, &mut now, &control);
    node.follow(&winning);
    run_to(&mut runner, BASE_HEIGHT + 9, &mut now);
    assert_eq!(
        runner.service().economic_chain().unwrap().tip().id,
        winning.tip().id
    );

    let scratch_dirs = Dirs::new();
    let scratch_node = MockNode::default();
    scratch_node.follow(&winning);
    let mut scratch = new_runner(
        &scratch_dirs,
        &scratch_node,
        MapProvider::default(),
        SourceBlockMode::IndexedReplay,
    );
    let mut scratch_now = 0;
    run_to(&mut scratch, BASE_HEIGHT + 9, &mut scratch_now);
    assert_eq!(state_bytes(&runner), state_bytes(&scratch));
}

/// Steps until the observer's tip is the losing branch's, then returns.
fn run_to_reorg(runner: &mut Runner, now: &mut u64, control: &BootstrapControl) {
    // The losing branch is shorter than the chain the node first followed,
    // so the observer reports a tip below its own: CursorAboveTip.
    for _ in 0..50 {
        *now += 11_000;
        let events = runner.step(*now, control).unwrap();
        if events
            .iter()
            .any(|e| matches!(e, NodeEvent::Reorganized { .. }))
        {
            return;
        }
    }
    panic!("no reorganization");
}
